(()=>{const paths={"arrow-left":"\n  <path d=\"m12 19-7-7 7-7\" />\n  <path d=\"M19 12H5\" />\n","rotate-ccw":"\n  <path d=\"M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8\" />\n  <path d=\"M3 3v5h5\" />\n","pause":"\n  <rect x=\"14\" y=\"4\" width=\"4\" height=\"16\" rx=\"1\" />\n  <rect x=\"6\" y=\"4\" width=\"4\" height=\"16\" rx=\"1\" />\n","play":"\n  <polygon points=\"6 3 20 12 6 21 6 3\" />\n","chevrons-up":"\n  <path d=\"m17 11-5-5-5 5\" />\n  <path d=\"m17 18-5-5-5 5\" />\n","circle-pause":"\n  <circle cx=\"12\" cy=\"12\" r=\"10\" />\n  <line x1=\"10\" x2=\"10\" y1=\"15\" y2=\"9\" />\n  <line x1=\"14\" x2=\"14\" y1=\"15\" y2=\"9\" />\n","octagon":"\n  <path d=\"M2.586 16.726A2 2 0 0 1 2 15.312V8.688a2 2 0 0 1 .586-1.414l4.688-4.688A2 2 0 0 1 8.688 2h6.624a2 2 0 0 1 1.414.586l4.688 4.688A2 2 0 0 1 22 8.688v6.624a2 2 0 0 1-.586 1.414l-4.688 4.688a2 2 0 0 1-1.414.586H8.688a2 2 0 0 1-1.414-.586z\" />\n","door-open":"\n  <path d=\"M13 4h3a2 2 0 0 1 2 2v14\" />\n  <path d=\"M2 20h3\" />\n  <path d=\"M13 20h9\" />\n  <path d=\"M10 12v.01\" />\n  <path d=\"M13 4.562v16.157a1 1 0 0 1-1.242.97L5 20V5.562a2 2 0 0 1 1.515-1.94l4-1A2 2 0 0 1 13 4.561Z\" />\n","door-closed":"\n  <path d=\"M18 20V6a2 2 0 0 0-2-2H8a2 2 0 0 0-2 2v14\" />\n  <path d=\"M2 20h20\" />\n  <path d=\"M14 12v.01\" />\n","wind":"\n  <path d=\"M12.8 19.6A2 2 0 1 0 14 16H2\" />\n  <path d=\"M17.5 8a2.5 2.5 0 1 1 2 4H2\" />\n  <path d=\"M9.8 4.4A2 2 0 1 1 11 8H2\" />\n","log-in":"\n  <path d=\"M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4\" />\n  <polyline points=\"10 17 15 12 10 7\" />\n  <line x1=\"15\" x2=\"3\" y1=\"12\" y2=\"12\" />\n","log-out":"\n  <path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\" />\n  <polyline points=\"16 17 21 12 16 7\" />\n  <line x1=\"21\" x2=\"9\" y1=\"12\" y2=\"12\" />\n","check":"\n  <path d=\"M20 6 9 17l-5-5\" />\n","arrow-up-right":"\n  <path d=\"M7 7h10v10\" />\n  <path d=\"M7 17 17 7\" />\n","train-front":"\n  <path d=\"M8 3.1V7a4 4 0 0 0 8 0V3.1\" />\n  <path d=\"m9 15-1-1\" />\n  <path d=\"m15 15 1-1\" />\n  <path d=\"M9 19c-2.8 0-5-2.2-5-5v-4a8 8 0 0 1 16 0v4c0 2.8-2.2 5-5 5Z\" />\n  <path d=\"m8 19-2 3\" />\n  <path d=\"m16 19 2 3\" />\n","layout-dashboard":"\n  <rect width=\"7\" height=\"9\" x=\"3\" y=\"3\" rx=\"1\" />\n  <rect width=\"7\" height=\"5\" x=\"14\" y=\"3\" rx=\"1\" />\n  <rect width=\"7\" height=\"9\" x=\"14\" y=\"12\" rx=\"1\" />\n  <rect width=\"7\" height=\"5\" x=\"3\" y=\"16\" rx=\"1\" />\n","gauge":"<path d=\"m12 14 4-4\"/><path d=\"M3.34 19a10 10 0 1 1 17.32 0\"/>","move-right":"<path d=\"M18 8l4 4-4 4M2 12h20\"/>","circle-alert":"<circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 8v4M12 16h.01\"/>"};
const icon=name=>`<svg data-icon="${name}" class="ui-icon" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[name]||''}</svg>`;
// Preserve SVG roots on every tick and draw paths inline so mobile WebKit
// can switch pause/resume glyphs without resolving an external SVG fragment.
function button(el,name,label,only=false){
if(!el)return;
let svg=el.querySelector('svg.ui-icon');
if(!svg){el.innerHTML=icon(name);svg=el.querySelector('svg.ui-icon');}
if(svg.getAttribute('data-icon')!==name){svg.innerHTML=paths[name]||'';svg.setAttribute('data-icon',name);}
let span=el.querySelector('span');
if(only){if(span)span.remove();}else{if(!span){span=document.createElement('span');el.append(span);}if(span.textContent!==label)span.textContent=label;}
if(el.getAttribute('aria-label')!==label)el.setAttribute('aria-label',label);
if(el.title!==label)el.title=label;
el.classList.toggle('icon-only',only);
}
const get=id=>document.getElementById(id);
function common(){document.querySelectorAll('.game-back,.dialog-back').forEach(el=>button(el,'arrow-left','返回游戏大厅',true));button(get('restart'),'rotate-ccw','重新开始驾驶',true);button(get('station-new'),'rotate-ccw','重新值班',true);}
function drive(s){get('pause')?.setAttribute('aria-pressed',String(s.paused));for(const [id,on] of [['power',s.notch>0],['coast',s.notch===0],['brake',s.notch<0]])get(id)?.setAttribute('aria-pressed',String(on));button(get('pause'),s.paused?'play':'pause',s.paused?'继续驾驶':'暂停驾驶',true);button(get('doors'),s.doorsOpen?'door-closed':'door-open',s.phase==='dwell'?'上下客中':s.doorsOpen?'关闭车门':'打开车门',true);button(get('power'),'gauge','牵引');button(get('coast'),'move-right','惰行');button(get('brake'),'circle-alert','制动');const d=get('depart');if(d&&!d.hidden)button(d,'train-front',s.paused?'已暂停':s.phase==='running'?'运行中':s.phase==='dwell'?'停站中':['finished','failed'].includes(s.phase)?'行程结束':s.doorsOpen?'关闭车门':'发车');}
function station(s){const start=get('station-start');if(start)button(start,s.phase==='paused'?'play':'train-front',start.textContent.replace(' →',''));button(get('station-pause'),s.phase==='paused'?'play':'pause',s.phase==='paused'?'继续值班':'暂停值班',true);for(let p=0;p<4;p++){const reserved=s.platforms[p]?.phase==='reserved';button(get('platform-receive-'+p),reserved?'check':'log-in',reserved?'已预留':'接车');button(get('platform-send-'+p),'log-out','发车');get('platform-receive-'+p)?.setAttribute('aria-label',(p+1)+'站台'+(reserved?'已预留':'接车'));get('platform-send-'+p)?.setAttribute('aria-label',(p+1)+'站台发车');}}
function init(){common();button(get('station-start'),'train-front','开始值班');button(get('start'),'train-front','进入驾驶室');button(get('retry'),'rotate-ccw','再驾驶一次');button(get('close-results'),'layout-dashboard','查看驾驶台');document.querySelectorAll('.rail-card strong').forEach(el=>{el.innerHTML='<span>'+el.textContent.replace(' ↗','')+'</span>'+icon('arrow-up-right');});const pause=get('station-pause');button(pause,'pause','暂停值班',true);document.querySelectorAll('[data-rate]').forEach(b=>b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const all=[...document.querySelectorAll('[data-rate]')],i=all.indexOf(b),n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;all[n].click();all[n].focus();}));}
globalThis.RailUI={icon,button,drive,station,init};})();
